const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

try {
  // Only run on Rust repos in execution order
  const result = execSync(
    'cd "$META_ROOT" && cargo check --workspace --all-targets 2>&1 | tail -50',
    { encoding: 'utf8' }
  );
  const logPath = process.env.META_ROOT + '/n8n/_workspace/verify-gate1-cargo-check.log';
  fs.writeFileSync(logPath, result);

  const hasError = /error[\[:]/.test(result);
  return { json: { gate: 'cargo_check', status: hasError ? 'fail' : 'pass', output_lines: result.split('\n').length } };
} catch(e) {
  fs.writeFileSync(process.env.META_ROOT + '/n8n/_workspace/verify-gate1-cargo-check.log', e.stdout?.toString() || e.message);
  return { json: { gate: 'cargo_check', status: 'fail', error: true, output_lines: (e.stdout?.toString() || '').split('\n').length } };
}

const { execSync } = require('child_process');
const fs = require('fs');

try {
  const result = execSync(
    'cd "$META_ROOT/n8n" && bun test _workspace/handoff/ 2>&1 | tail -30',
    { encoding: 'utf8' }
  );
  fs.writeFileSync(process.env.META_ROOT + '/n8n/_workspace/verify-gate2-bun-test.log', result);
  const hasFail = /failed|error/.test(result.toLowerCase());
  return { json: { gate: 'bun_test', status: hasFail ? 'fail' : 'pass', output_lines: result.split('\n').length } };
} catch(e) {
  fs.writeFileSync(process.env.META_ROOT + '/n8n/_workspace/verify-gate2-bun-test.log', e.stdout?.toString() || e.message);
  return { json: { gate: 'bun_test', status: 'fail', error: true } };
}

const { execSync } = require('child_process');
const fs = require('fs');

try {
  const result = execSync(
    'cd "$META_ROOT/n8n" && bunx biome check packages/cli --write 2>&1 | tail -30',
    { encoding: 'utf8' }
  );
  fs.writeFileSync(process.env.META_ROOT + '/n8n/_workspace/verify-gate3-biome-lint.log', result);
  const hasError = /error/.test(result.toLowerCase()) && !result.includes('checked');
  return { json: { gate: 'biome_lint', status: hasError ? 'fail' : 'pass', output_lines: result.split('\n').length } };
} catch(e) {
  fs.writeFileSync(process.env.META_ROOT + '/n8n/_workspace/verify-gate3-biome-lint.log', e.stdout?.toString() || e.message);
  return { json: { gate: 'biome_lint', status: 'fail', error: true } };
}

const http = require('http');

module.exports = function(items) {
  return new Promise((resolve) => {
    try {
      const req = http.get('http://localhost:5678/healthz', (res) => {
        let body = '';
        res.on('data', d => body += d);
        res.on('end', () => {
          resolve({ json: { gate: 'run_n8n_smoke', status: res.statusCode === 200 ? 'pass' : 'fail' } });
        });
      });
      req.setTimeout(5000, () => {
        req.destroy();
        resolve({ json: { gate: 'run_n8n_smoke', status: 'skip', reason: 'n8n not reachable' } });
      });
    } catch(e) {
      resolve({ json: { gate: 'run_n8n_smoke', status: 'skip', reason: e.message } });
    }
  });
};

=const results = [
  $json.gate === 'cargo_check' ? $json : null,
  $.gate_2_bun_test?.json || { gate: 'bun_test', status: 'unverified' },
  $.gate_3_biome_lint?.json || { gate: 'biome_lint', status: 'unverified' }
].filter(Boolean);

const allPass = results.every(r => r.status === 'pass');
const blockedItems = results.filter(r => r.status === 'fail').map(r => r.gate);

return {
  json: {
    gate_results: results,
    overall: allPass ? 'PASS' : 'FAIL',
    blocked_gates: blockedItems,
    cycles_total: results.length
  }
};
